mapper.select:
SELECT s.session_id, s.qwen_session_id, s.user_key, s.user_id, u.user_name, u.nick_name, s.client_id, s.client_ip, s.model_name, s.voice_name, s.status, s.started_at, s.ended_at, s.duration_ms, s.message_count, s.input_text_chars, s.output_text_chars, s.close_reason, s.create_time, s.update_time FROM ai_voice_session s LEFT JOIN sys_user u ON u.user_id = s.user_id
AND (u.user_name LIKE CONCAT('%', #{userName}, '%') OR u.nick_name LIKE CONCAT('%', #{userName}, '%') OR s.user_key LIKE CONCAT('%', #{userName}, '%'))
AND s.status = #{status}
AND s.model_name LIKE CONCAT('%', #{modelName}, '%')
AND s.started_at >= #{params.beginTime}
AND s.started_at <= #{params.endTime}
ORDER BY s.started_at DESC

SELECT m.memory_id, m.user_id, u.user_name, u.nick_name, m.memory_key,
       m.category, m.memory_value, m.confidence, m.source_session_id,
       m.status, m.last_used_at, m.create_time, m.update_time
FROM ai_user_memory m
LEFT JOIN sys_user u ON u.user_id = m.user_id


        AND (u.user_name LIKE CONCAT('%', #{userName}, '%')
             OR u.nick_name LIKE CONCAT('%', #{userName}, '%'))


        AND m.category = #{category}


        AND m.status = #{status}


        AND m.update_time >= #{params.beginTime}


        AND m.update_time <= #{params.endTime}


ORDER BY m.update_time DESC
